{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is neither documented nor ruled out."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7 are reinterpreted as consistency across repeated AI evaluations. Relevant precision evidence is insufficient: rating 0, not evidence of inadequate stability. Human retest intervals do not directly apply."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Absence of repetition leaves stability unknown; it does not demonstrate instability."
        }
      ],
      "instrument_review": "Under EFPA 9.3/9.7, reinterpreted for repeated AI runs, no repeatability findings are available. Precision remains unrateable from the supplied evidence, rating 0. Not conducting repeats is distinct from observing unstable scores."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "Repeated evaluations used the same stated conditions."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The range meets the report's stated stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 accommodates this alternative precision evidence, with 9.3 informing repeatability. The findings support stability for the tested system and conditions. The local threshold is not an EFPA reliability coefficient or sufficient grounds for an excellent rating."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings",
          "reason": "The developers examined scores across repeated evaluations under matching conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the stated stability threshold of at most two percentage points."
        }
      ],
      "instrument_review": "Under EFPA 9.7, the repeatability results are inadequate, rating 1, for the stated stability requirement. This is adverse evidence rather than missing evidence. If repeatability is critical to comparison, EFPA limits use to research or exceptional expert use."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation guidance supplies no evidence of repeated evaluations."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The new instructions do not establish consistency across runs."
        }
      ],
      "instrument_review": "The installation instructions relate to EFPA 6.3.8, software and technical support. They do not resolve missing precision evidence under 9.3/9.7, which remains rating 0. Documentation quality and measurement quality require separate judgements."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A achieved more correct solutions in the reported grid evaluation."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "These results do not establish a difference in general intelligence across domains."
        }
      ],
      "instrument_review": "EFPA 3.2 and 10.1 support describing the observed score comparison within its stated scope. Sections 10.3 and 10.5 require evidence for broader interpretations. General intelligence is unsupported, but that broader claim is outside this benchmark's intended use."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60",
          "reason": "A performed better on the evaluated grid puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "Declaring a broad intended use does not supply evidence supporting it."
        }
      ],
      "instrument_review": "EFPA 6.1 and 10.1–10.5 require evidence matching the intended interpretation. Grid performance alone leaves validity for selecting greater general intelligence insufficiently supported. Under EFPA's critical-quality guidance, this intended selection use should be restricted to research or exceptional expert use pending supporting evidence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "Test scores alone do not establish improved real workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "The randomized trial supports better correctness with A in the studied workshop; the reported difference interval is entirely positive."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings do not establish an improvement in unmeasured safety outcomes."
        }
      ],
      "instrument_review": "EFPA 10.3.1.6 covers the randomized comparison; 10.3.2 informs evaluation of decision correctness as an external outcome. Preregistration, random allocation, blinded checking and reported uncertainty strengthen support for the local intended use. Section 10.5 does not justify extending this finding to safety or other workshops. Inspectors are trial participants, not the AI systems being assessed."
    }
  ],
  "closing_note": "The request for a complete model and the instruction that full forms are unnecessary are read together as requiring relevant original EFPA sections for each probe. AI systems replace human test takers only where explicitly reinterpreted; human-specific disability, age-norm and personal-feedback questions are inapplicable here. Unreported properties remain unknown, not automatically inadequate. Probe labels are separate from EFPA ratings; no aggregate quality score is calculated. Source: EFPA Test Review Model 2025, version 5.0, supplied extraction, https://www.efpa.eu/, CC BY-SA 4.0. This review implies no EFPA endorsement."
}
